const items = $input.all();

// Función para limpiar texto para ManyChat
function cleanTextForManyChat(text) {
  const textStr = typeof text === 'string' ? text : String(text);
  return textStr
    .replace(/\n+/g, ' ')
    .replace(/"/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Función para extraer JSON de texto que puede tener contenido adicional
function extractJSON(text) {
  try {
    // Intentar parsear directamente primero
    return JSON.parse(text);
  } catch (error) {
    // Si falla, buscar JSON dentro del texto
    const jsonMatches = text.match(/\{[^{}]*\[[^\]]*\][^{}]*\}/g) || 
                       text.match(/\[[^\]]*\]/g);

    if (jsonMatches && jsonMatches.length > 0) {
      try {
        return JSON.parse(jsonMatches[0]);
      } catch (parseError) {
        throw new Error('No se pudo parsear el JSON encontrado');
      }
    }
    throw new Error('No se encontró JSON válido en el texto');
  }
}

const processedItems = [];

items.forEach(item => {
  const rawOutput = item.json.output;

  try {
    // Intentar extraer y parsear el JSON
    const parsedData = extractJSON(rawOutput);
    let messages = [];

    // Determinar el formato del JSON parseado
    if (Array.isArray(parsedData)) {
      // Caso 1: Array directo ["msg1", "msg2"]
      messages = parsedData;
    } else if (parsedData.output && Array.isArray(parsedData.output)) {
      // Caso 2: Objeto con array {output: ["msg1", "msg2"]}
      messages = parsedData.output;
    } else if (parsedData.messages && Array.isArray(parsedData.messages)) {
      // Caso 3: Objeto con messages {messages: ["msg1", "msg2"]}
      messages = parsedData.messages;
    } else {
      // Caso 4: Cualquier otro formato, convertir a string
      messages = [JSON.stringify(parsedData)];
    }

    // Procesar cada mensaje
    if (messages.length > 0) {
      messages.forEach((message, index) => {
        processedItems.push({
          json: {
            output: cleanTextForManyChat(message),
            messageIndex: index + 1,
            totalMessages: messages.length,
            originalItemIndex: items.indexOf(item),
            parseStatus: 'success'
          }
        });
      });
    } else {
      // Array vacío
      processedItems.push({
        json: {
          output: "Error: El agente devolvió un array vacío",
          messageIndex: 1,
          totalMessages: 1,
          originalItemIndex: items.indexOf(item),
          parseStatus: 'empty_array'
        }
      });
    }

  } catch (error) {
    // Si no se puede parsear como JSON, tratar como texto plano
    processedItems.push({
      json: {
        output: cleanTextForManyChat(rawOutput),
        messageIndex: 1,
        totalMessages: 1,
        originalItemIndex: items.indexOf(item),
        parseStatus: 'fallback_text',
        parseError: error.message
      }
    });
  }
});

return processedItems;

